function Timer() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(id); // تنظيف عند إزالة المكوّن
  }, []);

  return <p>{seconds} ثانية</p>;
}

