function Tooltip() {
  const ref = useRef(null);
  const [top, setTop] = useState(0);

  useLayoutEffect(() => {
    const { height } = ref.current.getBoundingClientRect();
    setTop(-height - 8); // نصحّح الموضع قبل أن يرى المستخدم أي وميض
  }, []);

  return <div ref={ref} style={{ position: "absolute", top }}>تلميح</div>;
}

